<template><div><div class="page-title"><div><div class="eyebrow">ASSET INVENTORY</div><h2>资产管理</h2></div><el-button type="primary" @click="openCreate">新增资产</el-button></div><el-form inline class="section-card"><el-input v-model="filters.ip_address" placeholder="IP 地址" clearable /><el-input v-model="filters.hostname" placeholder="主机名" clearable /><el-select v-model="filters.status" placeholder="状态" clearable><el-option label="active" value="active"/><el-option label="inactive" value="inactive"/></el-select><el-button @click="load">查询</el-button></el-form><div v-loading="loading" class="table-wrap"><el-table :data="assets"><el-table-column prop="asset_name" label="名称"/><el-table-column prop="ip_address" label="IP"/><el-table-column prop="hostname" label="主机名"/><el-table-column prop="asset_type" label="类型"/><el-table-column prop="importance" label="重要性"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="210"><template #default="{row}"><el-button link type="primary" @click="detail(row.id)">详情</el-button><el-button link @click="edit(row)">编辑</el-button><el-button link type="danger" @click="disable(row)">停用</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!assets.length" description="暂无资产数据"/></div><el-pagination v-if="total" class="section-card" layout="prev, pager, next" :page-size="10" :total="total" v-model:current-page="page" @current-change="load"/><el-dialog v-model="formVisible" :title="editing?'编辑资产':'新增资产'" width="520px"><el-form :model="form" label-width="90px"><el-form-item label="名称"><el-input v-model="form.asset_name"/></el-form-item><el-form-item label="类型"><el-input v-model="form.asset_type" placeholder="server / database"/></el-form-item><el-form-item label="IP 地址"><el-input v-model="form.ip_address"/></el-form-item><el-form-item label="主机名"><el-input v-model="form.hostname"/></el-form-item><el-form-item label="操作系统"><el-input v-model="form.os_info"/></el-form-item><el-form-item label="重要程度"><el-input-number v-model="form.importance" :min="1" :max="5"/></el-form-item><el-form-item label="备注"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="formVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog><el-drawer v-model="detailVisible" title="资产详情" size="430px"><el-descriptions v-if="selected" :column="1" border><el-descriptions-item label="名称">{{selected.asset_name}}</el-descriptions-item><el-descriptions-item label="IP">{{selected.ip_address}}</el-descriptions-item><el-descriptions-item label="主机名">{{selected.hostname}}</el-descriptions-item><el-descriptions-item label="系统">{{selected.os_info||'未填写'}}</el-descriptions-item><el-descriptions-item label="服务">{{selected.services?.map(s=>`${s.port}/${s.protocol}`).join(', ')||'暂无'}}</el-descriptions-item><el-descriptions-item label="备注">{{selected.description||'暂无'}}</el-descriptions-item></el-descriptions></el-drawer></div></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from "vue"; import { ElMessage, ElMessageBox } from "element-plus"; import client from "../api/client"; import type { Asset } from "../api/types";
const assets=ref<Asset[]>([]),total=ref(0),page=ref(1),loading=ref(false),saving=ref(false),formVisible=ref(false),detailVisible=ref(false),editing=ref(false),selected=ref<Asset|null>(null),editId=ref(0); const filters=reactive({ip_address:"",hostname:"",status:""}); const form=reactive({asset_name:"",asset_type:"server",ip_address:"",hostname:"",os_info:"",importance:3,description:""});
const load=async()=>{loading.value=true;try{const params={page:page.value,page_size:10,...Object.fromEntries(Object.entries(filters).filter(([,value])=>value))};const r=(await client.get("/assets",{params})).data;assets.value=r.data;total.value=r.total;}catch{assets.value=[];}finally{loading.value=false;}};const reset=()=>Object.assign(form,{asset_name:"",asset_type:"server",ip_address:"",hostname:"",os_info:"",importance:3,description:""});const openCreate=()=>{editing.value=false;reset();formVisible.value=true};const edit=(a:Asset)=>{editing.value=true;editId.value=a.id;Object.assign(form,a);formVisible.value=true};const save=async()=>{saving.value=true;try{const payload=Object.fromEntries(Object.entries(form).filter(([key,value])=>key==="importance"||value!==""));if(editing.value) await client.patch(`/assets/${editId.value}`,payload);else await client.post("/assets",payload);ElMessage.success("保存成功");formVisible.value=false;await load();}catch(error:any){const detail=error.response?.data?.detail;ElMessage.error(Array.isArray(detail)?"参数格式不正确，请检查 IP 地址等字段":(detail||"保存失败，请检查权限和参数"));}finally{saving.value=false;}};const detail=async(id:number)=>{try{selected.value=(await client.get(`/assets/${id}`)).data;detailVisible.value=true;}catch{ElMessage.error("无法读取资产详情")}};const disable=async(a:Asset)=>{try{await ElMessageBox.confirm(`确定停用资产“${a.asset_name}”？`,"确认操作",{type:"warning"});await client.delete(`/assets/${a.id}`);ElMessage.success("资产已停用");await load();}catch(error:any){if(error === "cancel" || error === "close") return;const detail=error.response?.data?.detail;ElMessage.error(Array.isArray(detail)?"停用请求参数不正确":(detail||"停用失败，请检查管理员权限"));}};onMounted(load);
</script>
